const MOTION={pt:['Ⅱ Pausar animações','▶ Retomar animações'],es:['Ⅱ Pausar animaciones','▶ Reanudar animaciones'],en:['Ⅱ Pause animations','▶ Resume animations']}[document.documentElement.lang.slice(0,2)]||['Ⅱ Pausar animações','▶ Retomar animações'];const reduce=matchMedia('(prefers-reduced-motion: reduce)');if(!reduce.matches)document.body.classList.add('js');const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));const motion=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('offscreen',!e.isIntersecting)));document.querySelectorAll('.hero-product,.ai-demo,.solution-visual').forEach(e=>motion.observe(e));const button=document.querySelector('#motion');let paused=reduce.matches;function update(){document.body.classList.toggle('paused',paused);button.setAttribute('aria-pressed',String(paused));button.textContent=paused?MOTION[1]:MOTION[0]}button.addEventListener('click',()=>{paused=!paused;update()});reduce.addEventListener('change',e=>{paused=e.matches;update();if(e.matches)document.querySelectorAll('.reveal').forEach(x=>x.classList.add('visible'))});document.addEventListener('visibilitychange',()=>document.body.classList.toggle('hidden',document.hidden));update();
// Seletor de idioma
(()=>{const btn=document.querySelector('.lang-btn'),menu=document.getElementById('lang-menu');if(!btn||!menu)return;const set=o=>{btn.setAttribute('aria-expanded',String(o));menu.hidden=!o;if(o)menu.querySelector('a').focus()};btn.addEventListener('click',()=>set(menu.hidden));document.addEventListener('click',e=>{if(!menu.hidden&&!e.target.closest('.lang'))set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){set(false);btn.focus()}});menu.addEventListener('keydown',e=>{if(!/Arrow(Up|Down)/.test(e.key))return;e.preventDefault();const a=[...menu.querySelectorAll('a')],i=a.indexOf(document.activeElement);a[(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length].focus()})})();

// Carrossel de cases
(()=>{const track=document.querySelector('.cases-track');if(!track)return;const btns=document.querySelectorAll('.cases-btn');const step=()=>track.querySelector('.case-card').offsetWidth+16;const sync=()=>{btns[0].disabled=track.scrollLeft<8;btns[1].disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-8};btns.forEach(b=>b.addEventListener('click',()=>track.scrollBy({left:step()*Number(b.dataset.dir),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})));track.addEventListener('scroll',sync,{passive:true});addEventListener('resize',sync);sync()})();

// Vídeos (cases e vídeo do hero) em modal; data-video aceita id do YouTube ou URL de .mp4
(()=>{const modal=document.getElementById('video-modal');if(!modal||!modal.showModal)return;const frame=modal.querySelector('.video-frame');let opener=null;const close=()=>modal.close();modal.addEventListener('close',()=>{frame.innerHTML='';opener?.focus()});modal.querySelector('.video-close').addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close()});const open=(src,label,from)=>{opener=from;frame.innerHTML=/\.(mp4|webm)(\?|$)/.test(src)?`<video src="${src}" controls autoplay playsinline></video>`:`<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(src)}?autoplay=1&rel=0" title="${label}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;modal.setAttribute('aria-label',label);modal.showModal()};document.querySelectorAll('[data-video]').forEach(b=>{if(!b.dataset.video)return;b.hidden=false;b.addEventListener('click',()=>open(b.dataset.video,b.getAttribute('aria-label'),b))})})();
